/**
 * @name ReDoS Data Flow
 * @description Track flow from function parameters to regex executions in mdurl
 * @kind path-problem
 * @problem.severity error
 * @id py/mdurl-redos-flow
 * @tags security
 *       external/cwe/cwe-1333
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.Concepts

module RedosFlowConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::ParameterNode p |
      p = source and
      p.getParameter().getName() != "self" and
      // Limit to parameters of functions defined in the mdurl package
      p.getLocation().getFile().getRelativePath().matches("src/mdurl/%")
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(RegexExecution re |
      sink = re.getString()
    )
  }
}

module RedosFlow = TaintTracking::Global<RedosFlowConfig>;
import RedosFlow::PathGraph

from RedosFlow::PathNode source, RedosFlow::PathNode sink, RegexExecution re
where RedosFlow::flowPath(source, sink)
  and sink.getNode() = re.getString()
select sink.getNode(), source, sink, "Regex execution with input from $@.", source.getNode(), "parameter"
